package ru.neverland.townyquests.cooperative;

import java.util.*;
import java.util.concurrent.*;
import org.bukkit.entity.Player;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.scheduler.BukkitTask;
import ru.neverland.core.*;

/** Optional cooperative projects are backed entirely by the Contracts materials ledger. No second resource/reward write. */
public final class CooperativeService {
    public record Template(String id,String title,String scope,String unlock,long minimum,Map<String,Long> needs){public Template{needs=Map.copyOf(needs);if(id==null||!id.matches("[a-z0-9_]{1,14}")||title==null||title.isBlank()||title.length()>128||!Set.of("SERVER","CITY").contains(scope)||unlock==null||!unlock.matches("joint_[a-z0-9_]{1,42}")||minimum<1||minimum>1_000_000_000||needs.isEmpty()||needs.size()>256)throw new IllegalArgumentException("Неверная смета общего проекта");long total=0;for(var e:needs.entrySet()){var material=org.bukkit.Material.matchMaterial(e.getKey());if(material==null||Set.of(org.bukkit.Material.AIR,org.bukkit.Material.CAVE_AIR,org.bukkit.Material.VOID_AIR).contains(material)||e.getValue()<1||e.getValue()>1_000_000_000L)throw new IllegalArgumentException("Неверный материал сметы "+e.getKey());total=Math.addExact(total,e.getValue());}if(minimum>total)throw new IllegalArgumentException("Порог участия больше сметы");}public void validateItems(){for(String key:needs.keySet())if(!Objects.requireNonNull(org.bukkit.Material.matchMaterial(key)).isItem())throw new IllegalArgumentException("Материал не является предметом: "+key);}}
    private final JavaPlugin plugin;private volatile Map<String,Template> templates=Map.of();private volatile String issue="Раздел ещё не загружен";private volatile boolean closed;
    private final CooperativeUnlockCache cache=new CooperativeUnlockCache();private BukkitTask task;
    public CooperativeService(JavaPlugin plugin){this.plugin=plugin;reload();task=SuiteScheduler.get().runTaskTimer(plugin,this::refresh,20,20);}
    public void reload(){try{var f=new java.io.File(plugin.getDataFolder(),"cooperative.yml");if(!f.isFile())plugin.saveResource("cooperative.yml",false);var y=new YamlConfiguration();y.load(f);if(!(y.get("enabled")instanceof Boolean enabled))throw new IllegalArgumentException("enabled: true или false");if(!enabled){templates=Map.of();issue="Общие стройки сейчас отключены";return;}var root=y.getConfigurationSection("templates");if(root==null||root.getKeys(false).size()>100)throw new IllegalArgumentException("Нужны templates: не более 100 смет");var next=new LinkedHashMap<String,Template>();for(String id:root.getKeys(false)){var row=root.getConfigurationSection(id);if(row==null)throw new IllegalArgumentException("Неверная смета "+id);var costs=row.getConfigurationSection("materials");if(costs==null)throw new IllegalArgumentException("Нет материалов "+id);var needs=new TreeMap<String,Long>();for(String key:costs.getKeys(false)){Object raw=costs.get(key);if(!(raw instanceof Number n))throw new IllegalArgumentException("Нужно целое количество "+key);needs.put(key,new java.math.BigDecimal(n.toString()).longValueExact());}Object min=row.get("minimum-city-credit");if(!(min instanceof Number number))throw new IllegalArgumentException("Нужен minimum-city-credit");var template=new Template(id,row.getString("title"),row.getString("scope"),row.getString("unlock"),new java.math.BigDecimal(number.toString()).longValueExact(),needs);template.validateItems();next.put(id,template);}templates=Map.copyOf(next);issue="";}catch(Exception error){templates=Map.of();issue="Настройки общих строек требуют проверки администратора";plugin.getLogger().warning(issue+": "+error.getMessage());}}
    public Map<String,Template> templates(){return templates;}public String issue(){return issue;}
    private ApiServices.Connection link(String capability){if(closed||!issue.isEmpty()||SuiteState.frozen(plugin.getName()))throw new IllegalStateException(issue.isEmpty()?"Общие стройки приостановлены":issue);var c=ApiServices.connect("NeverLandTownyContracts","ru.neverland.mintcontracts.api.ServerMaterialsApi",1,capability,"cooperativeReady");if(!c.ready())throw new IllegalStateException("Серверный склад общих строек временно недоступен");try{if(!Boolean.TRUE.equals(c.invoke("cooperativeReady",new Class<?>[0])))throw new IllegalStateException("Серверный склад ожидает проверки");}catch(ReflectiveOperationException error){throw new IllegalStateException("Серверный склад ожидает проверки",error);}return c;}
    @SuppressWarnings("unchecked")private <T>CompletionStage<T> call(String method,Class<?>[] types,Object... args){try{Object value=link(method).invoke(method,types,args);if(!(value instanceof CompletionStage<?> stage))throw new IllegalStateException("Несовместимый ответ склада");return(CompletionStage<T>)stage;}catch(Exception|LinkageError error){return CompletableFuture.failedFuture(error);}}
    public CompletionStage<List<Map<String,Object>>> projects(int page){return call("cooperativeProjects",new Class<?>[]{int.class},page);}
    public CompletionStage<Map<String,Object>> project(String id){return call("cooperativeProject",new Class<?>[]{String.class},id);}
    public CompletionStage<List<Map<String,Object>>> receipts(UUID town,int page){return call("cooperativeReceipts",new Class<?>[]{UUID.class,int.class},town,page);}
    public CompletionStage<List<Map<String,Object>>> history(String project){return call("cooperativeHistory",new Class<?>[]{String.class},project);}
    @SuppressWarnings("unchecked")public List<Map<String,Object>> orders(Player player)throws Exception{return(List<Map<String,Object>>)link("cooperativeOrders").invoke("cooperativeOrders",new Class<?>[]{Player.class},player);}
    public CompletionStage<Void> deliver(Player player,UUID order,String project){return call("cooperativeDeliver",new Class<?>[]{Player.class,UUID.class,String.class},player,order,project);}
    public CompletionStage<Map<String,Object>> plan(Template template,UUID town,String actor){template.validateItems();String owner=template.scope().equals("CITY")?Objects.requireNonNull(town,"Город не найден").toString():"";String id=template.scope().equals("CITY")?template.id()+"_"+owner.replace("-",""):template.id();return call("cooperativePlan",new Class<?>[]{String.class,String.class,String.class,String.class,String.class,long.class,Map.class,String.class},id,template.title(),template.scope(),owner,template.unlock(),template.minimum(),template.needs(),actor);}
    public CompletionStage<Map<String,Object>> finish(String id,boolean cancel,String actor,String reason){return call("cooperativeFinish",new Class<?>[]{String.class,boolean.class,String.class,String.class},id,cancel,actor,reason);}
    /** Prefix separates optional cooperative unlock uncertainty from ordinary saved city-chain results. */
    public boolean unlocked(UUID town,String key){try(var guard=SuiteState.guard()){if(town==null||key==null||!key.startsWith("joint_"))return false;link("cooperativeUnlocks");long now=System.nanoTime();cache.watch(town,now);request(town,now);return cache.read(town,key,now);}}
    private void request(UUID town,long now){if(!cache.start(town,now))return;this.<Set<String>>call("cooperativeUnlocks",new Class<?>[]{UUID.class},town).whenComplete((values,error)->{if(closed||!plugin.isEnabled())return;SuiteScheduler.get().runTask(plugin,()->{if(!closed)cache.complete(town,values,System.nanoTime(),error==null&&values!=null);});});}
    private void refresh(){long now=System.nanoTime();for(UUID town:cache.due(now))request(town,now);}
    public void stop(){closed=true;if(task!=null)task.cancel();cache.clear();}
}
